import sys

INF = 1000000000

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])
    if n > m:
        n, m = m, n

    size = 1 << n
    current = [[INF] * size for _ in range(size)]
    current[0][0] = 0

    for step in range(m):
        next_state = [[INF] * size for _ in range(size)]
        for c0 in range(size):
            for c1 in range(size):
                if current[c0][c1] != INF:
                    limit = 1 if step == m - 1 else size
                    for c2 in range(limit):
                        done_mask = 0
                        for i in range(n):
                            if ((1 << i) & c1) == 0:
                                up = i - 1
                                down = i + 1
                                if up >= 0 and ((1 << up) & c1) != 0:
                                    done_mask |= 1 << i
                                if down < n and ((1 << down) & c1) != 0:
                                    done_mask |= 1 << i
                                if ((1 << i) & c0) != 0:
                                    done_mask |= 1 << i
                                if ((1 << i) & c2) != 0:
                                    done_mask |= 1 << i
                        new_val = current[c0][c1] + n - bin(done_mask).count('1')
                        if new_val < next_state[c1][c2]:
                            next_state[c1][c2] = new_val
        current = next_state

    result = INF
    for row in current:
        for val in row:
            if val < result:
                result = val
    print(n * m - result)

